INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 English Vocabulary Practice: Grammar, Punctuation, and Spelling', 'This quiz focuses on vocabulary related to English grammar, punctuation, and spelling as outlined in the 2025 national curriculum for Key Stage 2. Students will practice understanding word meanings, prefixes, punctuation marks, sentence types, and grammatical terms to improve their language skills and comprehension.', '[{"id": "q1", "type": "mcq", "question": "Circle the word that is a synonym of the word ''bumpy''.", "hint": "Think of a word that means uneven or rough.", "explanation": "The word ''uneven'' means not smooth or flat, which is a synonym of ''bumpy''. ''Sore'' relates to pain, ''smooth'' is the opposite of bumpy, and ''low'' refers to height.", "correctAnswer": "a", "options": [{"id": "a", "text": "uneven"}, {"id": "b", "text": "sore"}, {"id": "c", "text": "smooth"}, {"id": "d", "text": "low"}]}, {"id": "q2", "type": "mcq", "question": "What does the prefix ''anti-'' mean in the word ''anticlockwise''?", "hint": "Prefixes often change the meaning of a word to its opposite or negation.", "explanation": "The prefix ''anti-'' means ''opposite'' or ''against''. In ''anticlockwise'', it means moving in the opposite direction to clockwise.", "correctAnswer": "b", "options": [{"id": "a", "text": "never"}, {"id": "b", "text": "opposite"}, {"id": "c", "text": "before"}, {"id": "d", "text": "without"}]}, {"id": "q3", "type": "multiSelect", "question": "Tick all the sentences that must end with a question mark.", "hint": "Questions ask something and usually end with a question mark.", "explanation": "Sentences that ask a direct question require a question mark at the end. Statements or indirect questions do not.", "correctAnswer": ["b", "d"], "options": [{"id": "a", "text": "How good it would be if Jay could come"}, {"id": "b", "text": "Is Jay going to come on Tuesday"}, {"id": "c", "text": "Jay asked if we could meet him on Tuesday"}, {"id": "d", "text": "Do you know if Jay is coming on Tuesday"}]}, {"id": "q4", "type": "mcq", "question": "Which sentence starts with an adverbial?", "hint": "An adverbial often tells when, where, or how something happens and can start a sentence.", "explanation": "The sentence ''After dinner, Kal is going to her room.'' starts with an adverbial phrase indicating time.", "correctAnswer": "b", "options": [{"id": "a", "text": "She is feeling tired, so Kal is going to her room."}, {"id": "b", "text": "After dinner, Kal is going to her room."}, {"id": "c", "text": "Arun told me that Kal is going to her room."}, {"id": "d", "text": "I wonder when Kal is going to her room."}]}, {"id": "q5", "type": "fillInBlank", "question": "Complete the sentence with the correct prefix: The prefix ''___'' can be added to ''charge'', ''cycle'', and ''cover'' to make new words.", "hint": "This prefix often means ''again'' or ''back''.", "explanation": "The prefix ''re-'' means ''again'' or ''back'', forming words like ''recharge'', ''recycle'', and ''recover''.", "correctAnswer": "re"}]', 'ef76faf5-707e-4387-9b7b-4b4894b6b548', NOW());

INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 Spelling and Vocabulary Practice', 'This quiz focuses on vocabulary related to spelling and word usage from the Key Stage 2 English grammar, punctuation, and spelling test. It helps students practice word meanings, synonyms, and correct usage in context.', '[{"id": "q1", "type": "fillInBlank", "question": "There was a brave ___ in the story.", "hint": "Think of a person who shows courage.", "explanation": "The word ''hero'' fits here as it means a person admired for bravery.", "correctAnswer": "hero"}, {"id": "q2", "type": "mcq", "question": "Which word best completes the sentence: \"The children walked home ___ the park.\"?", "hint": "The word should describe movement through or across a place.", "explanation": "The correct answer is ''through'' because it means moving in one side and out the other side of something.", "correctAnswer": "a", "options": [{"id": "a", "text": "through"}, {"id": "b", "text": "around"}, {"id": "c", "text": "beside"}, {"id": "d", "text": "under"}]}, {"id": "q3", "type": "multiSelect", "question": "Select all words that can mean ''reward'' or ''something given for good work''.", "hint": "Think of words related to prizes or recognition.", "explanation": "Both ''prize'' and ''reward'' mean something given in recognition of effort or achievement.", "correctAnswer": ["a", "c"], "options": [{"id": "a", "text": "reward"}, {"id": "b", "text": "punishment"}, {"id": "c", "text": "prize"}, {"id": "d", "text": "penalty"}, {"id": "e", "text": "gift"}]}, {"id": "q4", "type": "fillInBlank", "question": "After a few days, the seeds ___ shoots.", "hint": "This word means to begin to grow.", "explanation": "''Sprout'' means to begin to grow or produce shoots.", "correctAnswer": "sprout"}, {"id": "q5", "type": "mcq", "question": "Which word means ''lightweight and easy to carry''?", "hint": "Think of something not heavy or bulky.", "explanation": "''Portable'' means easy to carry or move because it is light or small.", "correctAnswer": "b", "options": [{"id": "a", "text": "heavy"}, {"id": "b", "text": "portable"}, {"id": "c", "text": "bulky"}, {"id": "d", "text": "fragile"}]}]', 'ef76faf5-707e-4387-9b7b-4b4894b6b548', NOW());

INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 English Grammar, Punctuation and Spelling Vocabulary Practice', 'This quiz focuses on vocabulary related to English grammar, punctuation, and spelling as presented in the 2022 Key Stage 2 national curriculum test. It helps students understand word meanings, grammatical terms, punctuation usage, and sentence structure to improve their language skills.', '[{"id": "q1", "type": "mcq", "question": "Which sentence must end with a question mark?", "hint": "Look for a sentence that asks something.", "explanation": "A question mark is used at the end of a sentence that asks a direct question. The sentence ''Shall we go round the fitness trail in the park'' is a question and requires a question mark.", "correctAnswer": "a", "options": [{"id": "a", "text": "Shall we go round the fitness trail in the park"}, {"id": "b", "text": "We could go tomorrow if you like"}, {"id": "c", "text": "What I really like is the rope bridge"}, {"id": "d", "text": "Let me know what you would like to do"}]}, {"id": "q2", "type": "multiSelect", "question": "Which sentences use commas correctly?", "hint": "Check if commas separate items in a list or clauses properly.", "explanation": "Correct comma usage separates items in a list without unnecessary commas before conjunctions and separates clauses clearly. The correct sentences are: ''The children could choose to play netball, cricket, hockey or tennis.'' and ''Painting, drawing, sculpture and print-making, were all options on the art day.''", "correctAnswer": ["b", "d"], "options": [{"id": "a", "text": "The band will perform at concerts in Belfast, Manchester, Birmingham, Nottingham and, Sheffield."}, {"id": "b", "text": "The children could choose to play netball, cricket, hockey or tennis."}, {"id": "c", "text": "Owls badgers, hedgehogs and bats are all nocturnal animals."}, {"id": "d", "text": "Painting, drawing, sculpture and print-making, were all options on the art day."}]}, {"id": "q3", "type": "fillInBlank", "question": "Complete the sentence with the correct word: The African elephant, ___ largest land mammal in the world, can weigh up to 6.6 tonnes.", "hint": "Insert punctuation to set off extra information about the elephant.", "explanation": "Commas are used to set off non-essential information in a sentence. The phrase ''the largest land mammal in the world'' is additional information about the African elephant and should be enclosed in commas.", "correctAnswer": "the"}, {"id": "q4", "type": "mcq", "question": "What is the word class of the underlined words in the sentence: ''I have two brothers. Brian is older and Stanley is younger than me.''?", "hint": "Consider if the words describe nouns, name things, or show actions.", "explanation": "The words ''older'' and ''younger'' describe the brothers, so they are adjectives because adjectives describe or modify nouns.", "correctAnswer": "a", "options": [{"id": "a", "text": "adjective"}, {"id": "b", "text": "noun"}, {"id": "c", "text": "adverb"}, {"id": "d", "text": "verb"}]}, {"id": "q5", "type": "multiSelect", "question": "Which words are synonyms of each other in the passage: ''The school will supply all meals during the trip. If parents wish to provide children with additional drinks, they may do so.''?", "hint": "Synonyms are words with similar meanings.", "explanation": "''Supply'' and ''provide'' both mean to give or make available, so they are synonyms.", "correctAnswer": ["b", "d"], "options": [{"id": "a", "text": "school"}, {"id": "b", "text": "supply"}, {"id": "c", "text": "meals"}, {"id": "d", "text": "provide"}, {"id": "e", "text": "children"}]}]', 'ef76faf5-707e-4387-9b7b-4b4894b6b548', NOW());

INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 Spelling and Vocabulary Practice', 'This quiz focuses on vocabulary and spelling skills based on the 2022 Key Stage 2 English grammar, punctuation, and spelling test. Students will practice word meanings, correct spelling, and usage in context to improve their language proficiency.', '[{"id": "q1", "type": "fillInBlank", "question": "The children were ___ the objects from smallest to largest.", "hint": "Think of a word that means to arrange in order.", "explanation": "The correct word is ''ordering'', which means to arrange items in a sequence or according to size or importance.", "correctAnswer": "ordering"}, {"id": "q2", "type": "mcq", "question": "Which word means ''not allowed'' as used in the sentence: ''Chewing gum is ___ in school''?", "hint": "It is the opposite of ''permitted''.", "explanation": "''Forbidden'' means not allowed or prohibited, which fits the context of the sentence.", "correctAnswer": "b", "options": [{"id": "a", "text": "allowed"}, {"id": "b", "text": "forbidden"}, {"id": "c", "text": "encouraged"}, {"id": "d", "text": "accepted"}]}, {"id": "q3", "type": "multiSelect", "question": "Select all words that are synonyms or closely related to ''award'' as used in the sentence: ''I was given a ___ award.''", "hint": "Think of words related to prizes or recognition.", "explanation": "Words like ''prize'' and ''trophy'' are synonyms or related to ''award'', which is a recognition for achievement.", "correctAnswer": ["a", "c", "e"], "options": [{"id": "a", "text": "prize"}, {"id": "b", "text": "punishment"}, {"id": "c", "text": "trophy"}, {"id": "d", "text": "penalty"}, {"id": "e", "text": "medal"}]}, {"id": "q4", "type": "fillInBlank", "question": "The spy used ___ ink to write his message.", "hint": "This type of ink is invisible or hidden.", "explanation": "''Invisible'' ink is used to write messages that cannot be seen easily, often used in secret communications.", "correctAnswer": "invisible"}, {"id": "q5", "type": "mcq", "question": "What is the best word to complete this sentence? ''Cross the busy road with ___. ''", "hint": "This word means paying close attention to avoid danger.", "explanation": "''Care'' means to be cautious and attentive, which is important when crossing a busy road.", "correctAnswer": "a", "options": [{"id": "a", "text": "care"}, {"id": "b", "text": "speed"}, {"id": "c", "text": "noise"}, {"id": "d", "text": "hurry"}]}]', 'ef76faf5-707e-4387-9b7b-4b4894b6b548', NOW());

